compare.check:
(args, got) => {
    const b = args[0];
    if (!Array.isArray(got) || got.length !== 9) return false;
    const seen = new Set();
    for (let r = 0; r < 9; r++) {
      if (!Array.isArray(got[r]) || got[r].length !== 9) return false;
      for (let c = 0; c < 9; c++) {
        const v = got[r][c];
        if (typeof v !== "string" || !/^[1-9]$/.test(v)) return false;
        if (b[r][c] !== "." && b[r][c] !== v) return false;
        for (const k of ["r" + r + v, "c" + c + v, "b" + (Math.floor(r / 3) * 3 + Math.floor(c / 3)) + v]) {
          if (seen.has(k)) return false;
          seen.add(k);
        }
      }
    }
    return true;
  }
